    float v00 = base[ih * in_stride_h + iw];
    float v01 = base[ih * in_stride_h + iw + 1];
    float v10 = base[(ih + 1) * in_stride_h + iw];
    float v11 = base[(ih + 1) * in_stride_h + iw + 1];

