    int iw_start = ow * pool_size;

    int base_offset = b * channels * in_height * in_width + c * in_height * in_width;

    float sum = 0.0f;
    float inv_pool = 1.0f / (float)(pool_size * pool_size);

    for (int ph = 0; ph < pool_size; ph++) {
